{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Private practice therapy focused on practical clinical work and steady progress." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <div class="site-bg">
    <svg class="site-pattern" role="img" aria-hidden="true"><use href="assets/img/pattern.svg#pattern"/></svg>
  </div>

  <header class="site-header">
    <div class="container nav-wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="/">Begin</a>
        <a href="about.html">Who</a>
        <a href="specialties.html">Focuses</a>
        <a href="approach.html">Practice</a>
        <a href="fees.html">Fees</a>
        <a href="faq.html">Questions</a>
        <a href="book.html" class="reserve">Reserve</a>
        <a href="contact.html">Reach</a>
      </nav>
      <div class="header-actions">
        <a class="phone" href="tel:{{PHONE}}">{{PHONE}}</a>
      </div>
    </div>
  </header>

  <main>
    <!-- Hero (sectionPack: hero) -->
    <section class="hero container" id="hero">
      <div class="hero-inner">
        <div class="hero-copy">
          <h1>{{BUSINESS_NAME}}</h1>
          <p class="tag">A measured clinical partner when life requires intention and care.</p>
          <p class="lead">I offer focused, evidence-informed psychotherapy for adults navigating transitions, overwhelm, or relationship strain. Sessions are grounded, private, and paced to your goals.</p>
          <div class="hero-cta">
            <a href="{{PRIMARY_CTA_URL}}" class="btn primary">{{PRIMARY_CTA_LABEL}}</a>
            <a href="contact.html" class="btn ghost">Message: {{EMAIL}}</a>
          </div>
          <p class="small">Sessions available via telehealth and limited in-person slots in {{CITY}}, {{STATE}}.</p>
        </div>
        <div class="hero-side">
          <div class="card subtle">
            <h4>Initial step</h4>
            <p>We start with a 20–30 minute consultation to clarify needs, scope, and fit. From there we co-design a path forward.</p>
            <a class="btn small" href="book.html">Schedule consult</a>
          </div>

          <div class="card proof-mini">
            <h5>Proof Gallery</h5>
            <div id="proof-gallery" class="gallery">
              <div class="slides">
                <blockquote class="slide active">"Therapeutic clarity without pressure — practical therapy that helped me plan each week." <span class="by">— client, 2024</span></blockquote>
                <blockquote class="slide">"A steady clinical voice when I needed structure for real-life changes." <span class="by">— client, 2023</span></blockquote>
                <blockquote class="slide">"Concrete tools and honest, respectful sessions. I felt seen and guided." <span class="by">— client, 2025</span></blockquote>
              </div>
              <div class="badges">
                <span class="badge" data-tooltip="Licensed clinical social worker — state licensure verified">LCSW</span>
                <span class="badge" data-tooltip="HIPAA-compliant telehealth platform used for secure sessions">Secure Telehealth</span>
                <span class="badge" data-tooltip="Years of training in adult psychotherapy and evidence-based methods">Qualified Clinician</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- Social proof (sectionPack: social_proof) -->
    <section class="social container" id="social-proof">
      <h2>What clients describe</h2>
      <div class="social-grid">
        <div class="testimonial-large" aria-live="polite">
          <div class="slides-large">
            <figure class="t-slide active"> 
              <blockquote>"I was able to change practical patterns — week by week — with grounded support."</blockquote>
              <figcaption>— A client in their 30s</figcaption>
            </figure>
            <figure class="t-slide"> 
              <blockquote>"Thoughtful listening paired with clear next steps for work and home life."</blockquote>
              <figcaption>— A client in their 40s</figcaption>
            </figure>
            <figure class="t-slide"> 
              <blockquote>"Helped me set boundaries without guilt and keep them."</blockquote>
              <figcaption>— A client in their 20s</figcaption>
            </figure>
          </div>
          <div class="gallery-controls">
            <button id="prev-test" aria-label="Previous testimonial">◀</button>
            <button id="next-test" aria-label="Next testimonial">▶</button>
          </div>
        </div>
        <aside class="credibility">
          <h3>Credentials & approach</h3>
          <ul>
            <li>State-licensed clinician with advanced training in adult psychotherapy</li>
            <li>Common approaches: integrative CBT, relational work, skills-based practice</li>
            <li>Short-term focused work and longer-term maintenance available</li>
          </ul>
        </aside>
      </div>
    </section>

    <!-- Benefits (sectionPack: benefits) -->
    <section class="benefits container" id="benefits">
      <h2>What working together looks like</h2>
      <ul class="benefit-list">
        <li>
          <h4>Clarity in moments of decision</h4>
          <p>We create practical, attainable steps so choices feel less chaotic and more doable.</p>
        </li>
        <li>
          <h4>Stabilizing routines</h4>
          <p>Small, evidence-informed habits that reduce overwhelm and support recovery.</p>
        </li>
        <li>
          <h4>Relational adjustments</h4>
          <p>Gentle, skill-based practices to improve communication and boundaries.</p>
        </li>
      </ul>
    </section>

    <!-- Process (sectionPack: process) with accordion for boundaries/confidentiality -->
    <section class="process container" id="process">
      <h2>How sessions are structured</h2>
      <p class="intro">Below are common questions about sessions, confidentiality, and limits of practice. If you have concerns, mention them in your consultation.</p>

      <div class="accordion" id="policy-accordion">
        <button class="acc-toggle" aria-expanded="false">Session boundaries & duration <span class="acc-icon">▾</span></button>
        <div class="acc-panel">
          <p>Typical sessions are 45–55 minutes. We agree on timing at the outset. If you are late, the session will generally end at the scheduled time to respect others' appointments.</p>
        </div>

        <button class="acc-toggle" aria-expanded="false">Confidentiality & professional scope <span class="acc-icon">▾</span></button>
        <div class="acc-panel">
          <p>Clinical notes and session content are confidential. I follow state regulations and professional ethical standards. Exceptions to confidentiality include imminent harm to self or others, suspected abuse of a minor or vulnerable adult, or a court order.</p>
        </div>

        <button class="acc-toggle" aria-expanded="false">Scheduling, cancellations, and fees <span class="acc-icon">▾</span></button>
        <div class="acc-panel">
          <p>Cancellation policies and fee structure are discussed at intake. Payment is expected unless other arrangements are agreed upon. There are no guarantees about progress — therapy is a collaborative effort.</p>
        </div>

        <button class="acc-toggle" aria-expanded="false">Telehealth & accessibility <span class="acc-icon">▾</span></button>
        <div class="acc-panel">
          <p>Telehealth sessions use a HIPAA-compliant platform. If you have specific accessibility needs, tell me so I can try to accommodate them.</p>
        </div>
      </div>

      <div class="crisis-note">
        <strong>Crisis and immediate safety:</strong>
        <p>If you are in immediate danger, please call 911 or local emergency services. If you are thinking about harming yourself, contact your nearest crisis line or the national suicide & crisis lifeline by dialing 988 (U.S.). This practice is not an emergency service.</p>
      </div>
    </section>

    <!-- FAQ (sectionPack: faq) -->
    <section class="faq container" id="faq">
      <h2>Common questions</h2>
      <dl>
        <dt>Do you accept insurance?</dt>
        <dd>I am a private-pay clinician. I can provide a receipt (superbill) that some clients submit to insurers for out-of-network reimbursement.</dd>

        <dt>What issues do you treat?</dt>
        <dd>I work with adults on anxiety, depression, life transitions, relationship concerns, and stress management. If your needs require specialized medical care, I can help coordinate referrals.</dd>

        <dt>What is your approach?</dt>
        <dd>I combine evidence-informed techniques with relational reflection — practical tools plus thoughtful clinical listening to support steady change.</dd>
      </dl>
    </section>

    <!-- CTA (sectionPack: cta) -->
    <section class="cta container" id="cta">
      <div class="cta-inner">
        <h3>Ready for the next step?</h3>
        <p>If you're seeking steady, confidential clinical work, book a consult to see if we're a good fit.</p>
        <div class="cta-actions">
          <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="contact.html">Contact: {{EMAIL}}</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="container">
      <div class="footer-grid">
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <address>{{CITY}}, {{STATE}}</address>
        </div>
        <div>
          <a href="tel:{{PHONE}}">{{PHONE}}</a>
          <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
        </div>
        <div>
          <nav class="foot-nav">
            <a href="about.html">About</a>
            <a href="fees.html">Fees</a>
            <a href="privacy.html">Privacy</a>
          </nav>
        </div>
      </div>
      <p class="muted">Licensed clinician. This site is for informational purposes and is not a substitute for urgent or emergency care.</p>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
