{"path":"assets/css/styles.css","content":"/* Glassmorphism-driven design, no external assets */
:root{
  --bg:#0f1724;
  --glass:rgba(255,255,255,0.06);
  --card:rgba(255,255,255,0.04);
  --accent:#7dd3fc;
  --muted:rgba(255,255,255,0.65);
  --max-width:1100px;
  --radius:14px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; background:var(--bg); color:#fff}
.container{max-width:var(--max-width);margin:0 auto;padding:28px}
.site-bg{position:fixed;inset:0;z-index:-2;opacity:0.8;}
.site-pattern{width:100%;height:100%;display:block}
.site-header{backdrop-filter: blur(6px);background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.005));border-bottom:1px solid rgba(255,255,255,0.03);position:sticky;top:0;z-index:10}
.nav-wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--accent);text-decoration:none;font-size:1.1rem}
.main-nav a{color:var(--muted);text-decoration:none;margin:0 10px;padding:12px 6px;border-radius:8px}
.main-nav a:hover{background:rgba(255,255,255,0.02);color:#fff}
.header-actions .phone{color:var(--muted);text-decoration:none}
.reserve{background:linear-gradient(90deg,var(--accent),#60a5fa);padding:8px 12px;border-radius:10px;color:#042;}
.hero{padding:60px 0;display:block}
.hero-inner{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start}
.hero-copy h1{font-size:2rem;margin:0 0 8px;color:#f8fafc}
.tag{color:var(--accent);font-weight:600}
.lead{color:var(--muted);margin:8px 0 18px}
.small{font-size:0.85rem;color:var(--muted)}
.btn{display:inline-block;text-decoration:none;padding:10px 16px;border-radius:10px;border:1px solid rgba(255,255,255,0.06);font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent),#60a5fa);color:#042}
.btn.ghost{background:transparent;color:var(--muted)}
.btn.small{padding:8px 10px}
.btn.large{padding:14px 20px}
.hero-side .card{background:var(--card);padding:16px;border-radius:12px;margin-bottom:14px;backdrop-filter:blur(8px)}
.proof-mini .badge{display:inline-block;margin-right:8px;padding:6px 8px;border-radius:8px;background:rgba(255,255,255,0.02);font-size:0.78rem;color:var(--muted);cursor:default}
.gallery{margin-top:10px}
.slides{position:relative;height:72px;overflow:hidden}
.slide{position:absolute;left:0;right:0;top:0;bottom:0;opacity:0;transform:translateY(6px);transition:opacity .5s,transform .5s;padding:6px 8px}
.slide.active{opacity:1;transform:none}
.by{display:block;font-size:0.75rem;color:var(--muted);margin-top:6px}
.social{padding:40px 0}
.social-grid{display:grid;grid-template-columns:2fr 1fr;gap:20px}
.testimonial-large{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));padding:18px;border-radius:12px}
.t-slide{display:none}
.t-slide.active{display:block}
.gallery-controls{display:flex;gap:8px;margin-top:10px}
.gallery-controls button{background:transparent;border:1px solid rgba(255,255,255,0.06);padding:8px;border-radius:8px;color:var(--muted)}
.credibility{background:var(--card);padding:16px;border-radius:12px}
.benefits{padding:36px 0}
.benefit-list{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;list-style:none;padding:0;margin:0}
.benefit-list li{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.008));padding:18px;border-radius:12px}
.process{padding:36px 0}
.accordion{margin-top:18px}
.acc-toggle{width:100%;text-align:left;padding:14px;border-radius:10px;border:1px solid rgba(255,255,255,0.03);background:transparent;color:#fff;margin-top:8px;cursor:pointer}
.acc-panel{max-height:0;overflow:hidden;transition:max-height .35s ease;padding:0 12px}
.acc-toggle[aria-expanded="true"]{background:rgba(255,255,255,0.02)}
.acc-toggle[aria-expanded="true"] + .acc-panel{padding:12px 12px;max-height:400px}
.acc-icon{float:right}
.crisis-note{margin-top:14px;padding:12px;background:rgba(255,59,48,0.06);border-left:4px solid rgba(255,59,48,0.3);border-radius:8px;color:#ffeef0}
.faq{padding:28px 0}
.faq dl{display:block}
.faq dt{font-weight:700;margin-top:12px}
.faq dd{margin:6px 0 12px;color:var(--muted)}
.cta{padding:36px 0}
.cta-inner{display:flex;align-items:center;justify-content:space-between;gap:20px}
.cta-actions .btn{margin-right:8px}
.site-footer{padding:20px 0;border-top:1px solid rgba(255,255,255,0.03);background:linear-gradient(180deg, rgba(0,0,0,0.02), transparent)}
.footer-grid{display:flex;justify-content:space-between;gap:20px}
.muted{color:var(--muted);font-size:0.9rem}
/* badge tooltip via pseudo-element */
.badge{position:relative}
.badge[data-tooltip]:hover::after{content:attr(data-tooltip);position:absolute;bottom:calc(100% + 10px);left:50%;transform:translateX(-50%);background:rgba(0,0,0,0.75);color:#fff;padding:8px 10px;border-radius:8px;white-space:nowrap;font-size:0.8rem;z-index:20}
@media(max-width:900px){
  .hero-inner{grid-template-columns:1fr}
  .social-grid{grid-template-columns:1fr}
  .benefit-list{grid-template-columns:1fr}
  .cta-inner{flex-direction:column;align-items:flex-start}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Simple testimonial rotator for the mini gallery and the large gallery
  function rotateSlides(containerSelector, interval){
    var container=document.querySelector(containerSelector);
    if(!container) return;
    var slides=[].slice.call(container.querySelectorAll('.slide, .t-slide'));
    if(!slides.length) return;
    var current=0;
    function show(i){
      slides.forEach(function(s,idx){
        s.classList.toggle('active', idx===i);
      });
    }
    show(0);
    var timer=setInterval(function(){
      current=(current+1)%slides.length;
      show(current);
    }, interval||6000);
    return {stop:function(){clearInterval(timer)}};
  }

  // Rotate mini proof slides
  rotateSlides('#proof-gallery .slides',6000);
  // Rotate larger testimonials
  var big = rotateSlides('.slides-large',7000);

  // Gallery manual controls
  document.getElementById('prev-test') && document.getElementById('prev-test').addEventListener('click', function(){
    var slides = document.querySelectorAll('.slides-large .t-slide');
    var activeIndex = Array.prototype.findIndex.call(slides, function(s){return s.classList.contains('active')});
    var next = (activeIndex - 1 + slides.length) % slides.length;
    slides[activeIndex].classList.remove('active');
    slides[next].classList.add('active');
  });
  document.getElementById('next-test') && document.getElementById('next-test').addEventListener('click', function(){
    var slides = document.querySelectorAll('.slides-large .t-slide');
    var activeIndex = Array.prototype.findIndex.call(slides, function(s){return s.classList.contains('active')});
    var next = (activeIndex + 1) % slides.length;
    slides[activeIndex].classList.remove('active');
    slides[next].classList.add('active');
  });

  // Accordion behaviour
  var accordions = document.querySelectorAll('.accordion .acc-toggle');
  accordions.forEach(function(btn){
    btn.addEventListener('click', function(){
      var expanded = btn.getAttribute('aria-expanded') === 'true';
      // collapse all for a simple single-open pattern
      accordions.forEach(function(b){b.setAttribute('aria-expanded','false');});
      if(!expanded){
        btn.setAttribute('aria-expanded','true');
      }
    });
    // allow keyboard enter/space
    btn.addEventListener('keydown', function(e){
      if(e.key === 'Enter' || e.key === ' '){
        e.preventDefault(); btn.click();
      }
    });
  });

  // Progressive enhancement: badges tooltips already via CSS, but add accessible title as well
  var badges = document.querySelectorAll('.badge[data-tooltip]');
  badges.forEach(function(b){
    if(!b.getAttribute('aria-label')) b.setAttribute('aria-label', b.getAttribute('data-tooltip'));
  });

  // Small accessibility: ensure focus outlines
  document.body.addEventListener('keyup', function(e){ if(e.key==='Tab') document.body.classList.add('show-focus'); });

})();
"} 
